"use client"

// Bollard UI — duration-input · MIT licence · https://bollard-ui.vercel.app/components/duration-input

import * as React from "react"
import { Timer, TriangleAlert } from "lucide-react"

import { cn } from "@/lib/utils"
import {
  compactDuration,
  formatDuration,
  parseDuration,
  type ColonMode,
  type DurationUnit,
} from "@/components/duration-input/duration"

export * from "@/components/duration-input/duration"

/** Default messages. `{typed}`, `{alt}`, `{limit}` are filled in. */
export const DURATION_MESSAGES = {
  error: "Couldn't read that. Try 1h 30m, 90m, 1.5h or 1:30.",
  clock: "{typed} hours means .{digits} of an hour, not {digits} minutes.",
  decimal: "decimal hours",
  ambiguous: "Is {typed} hours and minutes, or minutes and seconds?",
  tooShort: "Shorter than the {limit} minimum.",
  tooLong: "Longer than the {limit} maximum.",
  use: "Use {value}",
  perDay: "{hours}-hour days",
}

export interface DurationInputProps
  extends Omit<React.ComponentProps<"input">, "value" | "defaultValue" | "onChange" | "type" | "min" | "max"> {
  /** Visible label. */
  label?: string
  /** Controlled text, as typed. */
  value?: string
  /** Initial text when uncontrolled. */
  defaultValue?: string
  /** Called with the text and the duration in seconds, or null while it can't be read, is ambiguous or out of range. */
  onValueChange?: (text: string, seconds: number | null) => void
  /** Unit of a bare number such as "90". */
  unit?: DurationUnit
  /** How "1:30" is read. "auto" uses min/max and asks when both readings fit. */
  colon?: ColonMode
  /** Smallest allowed duration, in seconds. */
  min?: number
  /** Largest allowed duration, in seconds. */
  max?: number
  /** Hours in a "day", e.g. 8 for work-day estimates. */
  hoursPerDay?: number
  /** Helper text shown while the field is empty. */
  hint?: string
  /** Override any of the default messages. */
  messages?: Partial<typeof DURATION_MESSAGES>
}

const fieldClass =
  "h-9 w-full min-w-0 rounded-md border bg-transparent px-3 text-base shadow-xs transition-[color,box-shadow] outline-none placeholder:text-muted-foreground focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 disabled:cursor-not-allowed disabled:opacity-50 md:text-sm dark:bg-input/30 aria-invalid:border-destructive data-warning:border-amber-500 dark:data-warning:border-amber-400"
const fixClass =
  "inline-flex h-6 items-center gap-1 rounded-md border border-amber-500/40 px-2 font-medium text-amber-900 transition-colors hover:bg-amber-500/10 dark:text-amber-200 outline-none focus-visible:ring-[3px] focus-visible:ring-ring/50"
const keyframes = `@keyframes cui-duration-input-flash{0%{background-color:rgb(16 185 129 / .3)}100%{background-color:transparent}}`

const fill = (template: string, values: Record<string, string | number>) =>
  template.replace(/\{(\w+)\}/g, (match, key: string) => String(values[key] ?? match))

/**
 * A duration field that reads "1h30", "90m", "1.5h", "1:30", "2d 4h" or "PT1H30M" and reads it back in
 * words, so what was understood is never a guess. It catches the timesheet classic, "1.50" typed for
 * 1 h 50 min (decimal hours make it 1 h 30 min), and a "1:30" that could be h:mm or m:ss: it settles
 * that from the min/max limits and asks only when both readings fit. Out-of-range values get a one-tap
 * clamp to the limit.
 */
export function DurationInput({
  label = "Duration",
  value,
  defaultValue = "",
  onValueChange,
  unit = "m",
  colon = "auto",
  min,
  max,
  hoursPerDay = 24,
  hint,
  messages,
  placeholder = "1h 30m",
  id,
  className,
  ref,
  ...props
}: DurationInputProps) {
  const [inner, setInner] = React.useState(defaultValue)
  const [flash, setFlash] = React.useState(0)
  const autoId = React.useId()
  const inputId = id ?? autoId
  const text = value ?? inner
  const t = { ...DURATION_MESSAGES, ...messages }
  const options = { unit, colon, min, max, hoursPerDay }
  const result = parseDuration(text, options)
  // Spell days out only when the user typed them, so a 9 h shift isn't shown as "1 day 1 hour".
  const days = /\d\s*d/i.test(text) ? hoursPerDay : undefined
  const words = (s: number) => formatDuration(s, days)

  const seconds = result.kind === "ok" ? result.seconds : null
  const limit = seconds === null ? null : min !== undefined && seconds < min ? min : max !== undefined && seconds > max ? max : null

  const commit = (next: string) => {
    const parsed = parseDuration(next, options)
    const ok = parsed.kind === "ok" && (min === undefined || parsed.seconds >= min) && (max === undefined || parsed.seconds <= max)
    if (value === undefined) setInner(next)
    onValueChange?.(next, ok && parsed.kind === "ok" ? parsed.seconds : null)
  }
  const apply = (s: number) => {
    commit(compactDuration(s, days))
    setFlash((n) => n + 1)
  }

  const typed = text.trim()
  let warning: React.ReactNode = null
  if (result.kind === "ambiguous") {
    warning = (
      <>
        <span className="py-1">{fill(t.ambiguous, { typed })}</span>
        <span className="flex flex-wrap gap-1">
          <button type="button" onClick={() => apply(result.hm)} className={fixClass}>{words(result.hm)}</button>
          <button type="button" onClick={() => apply(result.ms)} className={fixClass}>{words(result.ms)}</button>
        </span>
      </>
    )
  } else if (limit !== null) {
    warning = (
      <>
        <span className="py-1">{fill(limit === min ? t.tooShort : t.tooLong, { limit: words(limit) })}</span>
        <button type="button" onClick={() => apply(limit)} className={fixClass}>{fill(t.use, { value: words(limit) })}</button>
      </>
    )
  } else if (result.kind === "ok" && result.clockMinutes !== undefined) {
    const number = typed.match(/[\d.,]+/)?.[0] ?? typed
    warning = (
      <>
        <span className="py-1">{fill(t.clock, { typed: number, digits: number.split(/[.,]/)[1] ?? "" })}</span>
        <button type="button" onClick={() => apply(result.clockMinutes as number)} className={fixClass}>
          {fill(t.use, { value: words(result.clockMinutes) })}
        </button>
      </>
    )
  }

  return (
    <div data-slot="duration-input" className={cn("grid w-full max-w-sm gap-1.5", className)}>
      <style>{keyframes}</style>
      <label htmlFor={inputId} className="w-fit text-sm font-medium">
        {label}
      </label>
      <input
        ref={ref}
        id={inputId}
        type="text"
        inputMode="text"
        autoComplete="off"
        spellCheck={false}
        value={text}
        placeholder={placeholder}
        onChange={(event) => commit(event.target.value)}
        aria-invalid={result.kind === "error" ? true : undefined}
        aria-describedby={`${inputId}-status`}
        data-warning={warning ? "" : undefined}
        className={fieldClass}
        {...props}
      />
      <div id={`${inputId}-status`} aria-live="polite" className="grid min-h-6 gap-1 text-xs">
        {result.kind === "error" ? (
          <p className="flex items-center gap-1.5 py-1 text-destructive">
            <TriangleAlert aria-hidden className="size-3.5 shrink-0" />
            {t.error}
          </p>
        ) : seconds !== null ? (
          <p
            key={flash}
            className={cn(
              "flex w-fit items-center gap-1.5 rounded-sm py-1 pr-1 text-muted-foreground",
              flash > 0 && "motion-safe:animate-[cui-duration-input-flash_400ms_ease-out]",
            )}
          >
            <Timer aria-hidden className="size-3.5 shrink-0" />
            <span>
              <span className="font-medium text-foreground">{words(seconds)}</span>
              {result.kind === "ok" && result.decimal && <> · {t.decimal}</>}
              {days && hoursPerDay !== 24 && <> · {fill(t.perDay, { hours: hoursPerDay })}</>}
            </span>
          </p>
        ) : !warning && hint ? (
          <p className="py-1 text-muted-foreground">{hint}</p>
        ) : null}
        {warning && (
          <p className="flex gap-1.5 text-amber-700 dark:text-amber-400">
            <span className="flex h-6 shrink-0 items-center">
              <TriangleAlert aria-hidden className="size-3.5" />
            </span>
            <span className="flex min-w-0 flex-wrap items-center gap-x-2 gap-y-1">{warning}</span>
          </p>
        )}
      </div>
    </div>
  )
}

// Bollard UI — duration-input · MIT licence · https://bollard-ui.vercel.app/components/duration-input

/** Unit for a bare number such as "90". */
export type DurationUnit = "d" | "h" | "m" | "s"
/** How "1:30" is read: hours and minutes, minutes and seconds, or decided from the limits (asking when both fit). */
export type ColonMode = "auto" | "h:mm" | "m:ss"

export interface DurationOptions {
  /** Unit of a bare number. */
  unit?: DurationUnit
  colon?: ColonMode
  /** Smallest allowed duration in seconds. */
  min?: number
  /** Largest allowed duration in seconds. */
  max?: number
  /** Hours in a "day" (8 for work-day estimates, as Jira does). */
  hoursPerDay?: number
}

export type DurationResult =
  | { kind: "empty" }
  | { kind: "error" }
  /** "1:30" where both readings fit: seconds for h:mm and for m:ss. */
  | { kind: "ambiguous"; hm: number; ms: number }
  | {
      kind: "ok"
      seconds: number
      /** Typed as decimal hours, e.g. "1.50": the reading where the decimals were minutes ("1 h 50 min"). */
      clockMinutes?: number
      /** Decimal hours that are correct but often misread, e.g. "1.5h", for a quiet note. */
      decimal?: boolean
    }

const UNIT_SECONDS = { d: 86400, h: 3600, m: 60, s: 1 }
const SMALLER: Record<DurationUnit, DurationUnit> = { d: "h", h: "m", m: "s", s: "s" }
const TOKEN = /^(\d+(?:\.\d+)?|\.\d+)\s*(days?|d|hours?|hrs?|h|minutes?|mins?|m|seconds?|secs?|s)?\s*(?:and\s*|,\s*)?/

const unitOf = (word: string): DurationUnit => (word[0] as DurationUnit)
const inRange = (s: number, { min = 0, max = Infinity }: DurationOptions) => s >= min && s <= max

/**
 * Parses "1h30", "90m", "1.5h", "1:30", "2d 4h", "1 hour 30 minutes" or ISO "PT1H30M" into seconds.
 * Flags decimal hours that look like clock minutes ("1.50" as 1 h 50 min) and a "1:30" that could be
 * h:mm or m:ss when the limits don't settle it.
 */
export function parseDuration(text: string, options: DurationOptions = {}): DurationResult {
  const { unit = "m", colon = "auto", hoursPerDay = 24 } = options
  const size = (u: DurationUnit) => (u === "d" ? hoursPerDay * 3600 : UNIT_SECONDS[u])
  const raw = text.trim().toLowerCase().replace(/(\d),(\d)/g, "$1.$2")
  if (!raw) return { kind: "empty" }

  const iso = raw.match(/^p(?:(\d+(?:\.\d+)?)d)?(?:t(?:(\d+(?:\.\d+)?)h)?(?:(\d+(?:\.\d+)?)m)?(?:(\d+(?:\.\d+)?)s)?)?$/)
  if (iso && raw !== "p") {
    const [d, h, m, s] = iso.slice(1).map((n) => Number(n ?? 0))
    return { kind: "ok", seconds: Math.round(d * size("d") + h * 3600 + m * 60 + s) }
  }

  const clock = raw.match(/^(\d+):(\d{1,2})(?::(\d{1,2}))?$/)
  if (clock) {
    const [a, b, c] = clock.slice(1).map(Number)
    if (b > 59 || (clock[3] && c > 59)) return { kind: "error" }
    if (clock[3]) return { kind: "ok", seconds: a * 3600 + b * 60 + c }
    const hm = a * 3600 + b * 60
    const ms = a * 60 + b
    if (colon === "h:mm") return { kind: "ok", seconds: hm }
    if (colon === "m:ss") return { kind: "ok", seconds: ms }
    if (inRange(hm, options) !== inRange(ms, options)) return { kind: "ok", seconds: inRange(hm, options) ? hm : ms }
    return { kind: "ambiguous", hm, ms }
  }

  let rest = raw
  let seconds = 0
  let last: DurationUnit | undefined
  let count = 0
  let clockMinutes: number | undefined
  let decimal = false
  while (rest) {
    const match = rest.match(TOKEN)
    if (!match) return { kind: "error" }
    const [whole, number, word] = match
    // "1h30": a trailing bare number takes the next unit down; a lone bare number takes `unit`.
    const u = word ? unitOf(word) : last ? SMALLER[last] : unit
    if (!word && last && whole.length !== rest.length) return { kind: "error" }
    const fraction = number.split(".")[1]
    if (u === "h" && fraction) {
      const asMinutes = Number(fraction)
      if (fraction.length === 2 && asMinutes >= 10 && asMinutes < 60 && asMinutes !== 25 && asMinutes !== 75) {
        clockMinutes = Math.floor(Number(number)) * 3600 + asMinutes * 60
      } else decimal = true
    }
    seconds += Number(number) * size(u)
    last = u
    count++
    rest = rest.slice(whole.length)
  }
  if (clockMinutes !== undefined && count > 1) clockMinutes = undefined
  return { kind: "ok", seconds: Math.round(seconds), clockMinutes, decimal }
}

const NAMES: Record<DurationUnit, [string, string]> = { d: ["day", "days"], h: ["hour", "hours"], m: ["minute", "minutes"], s: ["second", "seconds"] }

/** Splits seconds into days, hours, minutes and seconds (days only when `hoursPerDay` is set). */
function parts(seconds: number, hoursPerDay?: number) {
  const out: [number, DurationUnit][] = []
  let rest = Math.round(seconds)
  for (const u of ["d", "h", "m", "s"] as DurationUnit[]) {
    const step = u === "d" ? (hoursPerDay ?? 0) * 3600 : UNIT_SECONDS[u]
    if (!step) continue
    const n = Math.floor(rest / step)
    rest -= n * step
    if (n) out.push([n, u])
  }
  return out
}

/** "1 hour 30 minutes". Days appear only when `hoursPerDay` is given. */
export function formatDuration(seconds: number, hoursPerDay?: number) {
  const list = parts(seconds, hoursPerDay)
  if (!list.length) return "0 minutes"
  return list.map(([n, u]) => `${n} ${NAMES[u][n === 1 ? 0 : 1]}`).join(" ")
}

/** "1h 30m": compact and unambiguous, used when a fix rewrites the field. */
export function compactDuration(seconds: number, hoursPerDay?: number) {
  return parts(seconds, hoursPerDay).map(([n, u]) => `${n}${u}`).join(" ") || "0m"
}
